import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

import '../design/design.dart';

/// Boot artwork generated by `tool/build_brand_assets.py`.
///
/// The emblem images are 288 dp canvases, the canvas Android 12+ uses for its
/// splash icon, so drawing one centred on screen lands exactly where the
/// system splash left the emblem.
abstract final class AgonezBootAssets {
  static const emblemInk = 'assets/brand/boot/emblem_ink.png';
  static const emblemRelief = 'assets/brand/boot/emblem_relief.png';
  static const wordmark = 'assets/brand/boot/wordmark.png';
  static const emblemCanvas = 288.0;
  static const wordmarkSize = Size(120, 23.1);
}

/// Launch screen shown while the app runtime starts.
///
/// The system splash stays up until [onFirstFrameReady] lets Flutter draw,
/// which happens once the emblem is decoded, so the first frame matches the
/// native splash. If startup takes longer than [skipIntroWithin], the emblem
/// rises and the wordmark opens; after [showProgressAfter] a gold hairline
/// shows that work continues. The app fades in as soon as [start] completes,
/// even mid-intro: nothing waits for its own sake.
class AgonezBoot extends StatefulWidget {
  const AgonezBoot({
    required this.start,
    required this.onFirstFrameReady,
    super.key,
  });

  /// Builds the app. Failures should resolve to an error screen.
  final Future<Widget> Function() start;

  /// Releases Flutter's deferred first frame.
  final VoidCallback onFirstFrameReady;

  static const skipIntroWithin = Duration(milliseconds: 300);
  static const showProgressAfter = Duration(milliseconds: 700);
  static const introDuration = Duration(milliseconds: 620);
  static const exitDuration = Duration(milliseconds: 280);
  static const quickExitDuration = Duration(milliseconds: 200);

  @override
  State<AgonezBoot> createState() => _AgonezBootState();
}

class _AgonezBootState extends State<AgonezBoot> with TickerProviderStateMixin {
  late final AnimationController _intro = AnimationController(
    vsync: this,
    duration: AgonezBoot.introDuration,
  );
  late final AnimationController _exit = AnimationController(
    vsync: this,
    duration: AgonezBoot.exitDuration,
  )..addStatusListener(_onExitStatus);
  late final AnimationController _glint = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 1100),
  );

  Widget? _app;
  bool _firstFrameReleased = false;
  bool _introStarted = false;
  bool _exitScheduled = false;
  bool _showProgress = false;
  bool _brandVisible = true;
  Timer? _introTimer;
  Timer? _progressTimer;

  bool get _reducedMotion => View.of(
    context,
  ).platformDispatcher.accessibilityFeatures.disableAnimations;

  @override
  void initState() {
    super.initState();
    widget.start().then((app) {
      if (!mounted) return;
      setState(() => _app = app);
      _maybeExit();
    });
  }

  void _onArtworkReady() {
    if (_firstFrameReleased) return;
    _firstFrameReleased = true;
    widget.onFirstFrameReady();
    if (_app != null) {
      _maybeExit();
      return;
    }
    _introTimer = Timer(AgonezBoot.skipIntroWithin, () {
      if (!mounted || _app != null || _reducedMotion) return;
      _introStarted = true;
      _intro.forward();
    });
    _progressTimer = Timer(AgonezBoot.showProgressAfter, () {
      if (!mounted || _app != null) return;
      setState(() => _showProgress = true);
      if (!_reducedMotion) _glint.repeat();
    });
  }

  void _onExitStatus(AnimationStatus status) {
    if (status != AnimationStatus.completed || !mounted) return;
    _glint.stop();
    setState(() => _brandVisible = false);
  }

  void _maybeExit() {
    if (_app == null || !_firstFrameReleased || _exitScheduled) return;
    _exitScheduled = true;
    _introTimer?.cancel();
    _progressTimer?.cancel();
    _exit.duration = _introStarted
        ? AgonezBoot.exitDuration
        : AgonezBoot.quickExitDuration;
    // The app builds its first frame under the still brand; fading starts on
    // the next frame so that build cost never stutters the animation.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _exit.forward();
    });
  }

  @override
  void dispose() {
    _introTimer?.cancel();
    _progressTimer?.cancel();
    _intro.dispose();
    _exit.dispose();
    _glint.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final app = _app;
    return Stack(
      textDirection: TextDirection.ltr,
      fit: StackFit.expand,
      children: [
        if (app != null)
          FadeTransition(
            key: const ValueKey('app'),
            opacity: _exit,
            child: app,
          ),
        if (_brandVisible)
          // The brand sits outside the app's MaterialApp, so it brings its
          // own media query and text direction.
          MediaQuery.fromView(
            key: const ValueKey('brand'),
            view: View.of(context),
            child: Directionality(
              textDirection: TextDirection.ltr,
              child: _BootBrand(
                intro: _intro,
                exit: _exit,
                glint: _glint,
                showProgress: _showProgress,
                onArtworkReady: _onArtworkReady,
              ),
            ),
          ),
      ],
    );
  }
}

class _BootBrand extends StatefulWidget {
  const _BootBrand({
    required this.intro,
    required this.exit,
    required this.glint,
    required this.showProgress,
    required this.onArtworkReady,
  });

  final Animation<double> intro;
  final Animation<double> exit;
  final Animation<double> glint;
  final bool showProgress;
  final VoidCallback onArtworkReady;

  @override
  State<_BootBrand> createState() => _BootBrandState();
}

class _BootBrandState extends State<_BootBrand> {
  bool _precaching = false;

  bool get _dark => MediaQuery.platformBrightnessOf(context) == Brightness.dark;

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    if (_precaching) return;
    _precaching = true;
    // Decode before the first frame: an image that pops in a frame late
    // would flash the bare background between the native splash and Flutter.
    Future.wait([
      precacheImage(
        AssetImage(
          _dark ? AgonezBootAssets.emblemRelief : AgonezBootAssets.emblemInk,
        ),
        context,
      ),
      precacheImage(const AssetImage(AgonezBootAssets.wordmark), context),
    ]).whenComplete(widget.onArtworkReady);
  }

  @override
  Widget build(BuildContext context) {
    final dark = _dark;
    final colors = dark ? AgonezThemeColors.dark : AgonezThemeColors.light;
    final reducedMotion = MediaQuery.disableAnimationsOf(context);
    final emblem = SizedBox.square(
      dimension: AgonezBootAssets.emblemCanvas,
      child: Image.asset(
        dark ? AgonezBootAssets.emblemRelief : AgonezBootAssets.emblemInk,
        color: dark ? colors.goldText : colors.textPrimary,
        colorBlendMode: BlendMode.srcIn,
        excludeFromSemantics: true,
      ),
    );
    final wordmark = Image.asset(
      AgonezBootAssets.wordmark,
      width: AgonezBootAssets.wordmarkSize.width,
      height: AgonezBootAssets.wordmarkSize.height,
      color: colors.textPrimary,
      colorBlendMode: BlendMode.srcIn,
      excludeFromSemantics: true,
    );
    // Final positions, in dp from the screen centre.
    const emblemLift = 34.0;
    const wordmarkCenter = 82.5;
    const progressCenter = 113.0;

    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: SystemUiOverlayStyle(
        statusBarColor: Colors.transparent,
        statusBarIconBrightness: dark ? Brightness.light : Brightness.dark,
        statusBarBrightness: dark ? Brightness.dark : Brightness.light,
        systemNavigationBarColor: colors.ground,
        systemNavigationBarIconBrightness: dark
            ? Brightness.light
            : Brightness.dark,
      ),
      child: Semantics(
        label: 'Agonez',
        child: ColoredBox(
          color: colors.ground,
          child: AnimatedBuilder(
            animation: Listenable.merge([widget.intro, widget.exit]),
            builder: (context, _) {
              final rise = Curves.easeOutCubic.transform(
                const Interval(0, 500 / 620).transform(widget.intro.value),
              );
              final open = Curves.easeOutCubic.transform(
                const Interval(120 / 620, 1).transform(widget.intro.value),
              );
              final out = widget.exit.value;
              return Opacity(
                opacity: 1 - out,
                child: Transform.scale(
                  scale: reducedMotion ? 1 : 1 + .05 * out,
                  child: Stack(
                    children: [
                      Center(
                        child: Transform.translate(
                          offset: Offset(0, -emblemLift * rise),
                          child: Transform.scale(
                            scale: 1 - .1 * rise,
                            child: emblem,
                          ),
                        ),
                      ),
                      Center(
                        child: Transform.translate(
                          offset: Offset(0, wordmarkCenter + 6 * (1 - open)),
                          child: Opacity(
                            opacity: open,
                            child: ClipRect(
                              child: Align(widthFactor: open, child: wordmark),
                            ),
                          ),
                        ),
                      ),
                      if (widget.showProgress)
                        Center(
                          child: Transform.translate(
                            offset: const Offset(0, progressCenter),
                            child: _Progress(
                              glint: widget.glint,
                              track: colors.line,
                              gold: colors.gold,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              );
            },
          ),
        ),
      ),
    );
  }
}

/// A 2 dp gold hairline with a glint that sweeps across while loading.
class _Progress extends StatelessWidget {
  const _Progress({
    required this.glint,
    required this.track,
    required this.gold,
  });

  final Animation<double> glint;
  final Color track;
  final Color gold;

  static const _width = 44.0;
  static const _glintWidth = _width * .4;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      key: const ValueKey('boot-progress'),
      borderRadius: BorderRadius.circular(1),
      child: SizedBox(
        width: _width,
        height: 2,
        child: ColoredBox(
          color: track,
          child: AnimatedBuilder(
            animation: glint,
            builder: (context, _) => Stack(
              children: [
                Positioned(
                  left: -_glintWidth + (_width + _glintWidth) * glint.value,
                  top: 0,
                  bottom: 0,
                  width: _glintWidth,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: LinearGradient(
                        colors: [
                          gold.withValues(alpha: 0),
                          gold,
                          gold.withValues(alpha: 0),
                        ],
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}
